// Xcode 27 refuses to build any target below iOS 15, and a few pods
// (SDWebImage, RNSVG and AsyncStorage resource bundles) still declare 9.0-13.4.
// Raise every pod target to the app's own minimum. ios/ is regenerated by
// `expo prebuild`, so the fix has to live here rather than in the Podfile.
const { withPodfile } = require('expo/config-plugins');

const MIN = '15.1';
const MARKER = '# nutrichef: pods deployment target';
const SNIPPET = `
    ${MARKER}
    installer.pods_project.targets.each do |t|
      t.build_configurations.each do |c|
        if c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'].to_f < ${MIN}
          c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${MIN}'
        end
      end
    end`;

module.exports = function withPodsDeploymentTarget(config) {
  return withPodfile(config, (cfg) => {
    const src = cfg.modResults.contents;
    if (!src.includes(MARKER)) {
      cfg.modResults.contents = src.replace(/post_install do \|installer\|/, (m) => m + SNIPPET);
    }
    return cfg;
  });
};
